import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { CSSProperties, useMemo, useEffect, useState } from 'react';
import {
  IProfitDetailsReport,
  IProfitDetails,
} from '../../../core/Interface/profitDetailReport.interface';
import usePageQuery from '../../../core/hooks/usePageQuery';
import { useProfitDetailsReportQuery, useGetUserQuery } from '../../posApi';
import useProfitDetailsReportColumns from './useProfitDetailsReportColumns';
import { IUserInfo } from '../../../core/Interface/user.interface';

const useProfitDetailsReport = () => {
  const { page, setPage } = usePageQuery();
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: profitDetailsReportData,
    isLoading,
    isFetching,
    error,
  } = useProfitDetailsReportQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText: '',
  });

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  useEffect(() => {
    setPage(pagination.pageIndex);
  }, [pagination.pageIndex, setPage]);

  const ProfitDetailsMemo = useMemo(() => {
    return profitDetailsReportData?.data as IProfitDetailsReport;
  }, [profitDetailsReportData?.data]);

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return (
      profitDetailsReportData &&
      ProfitDetailsMemo.data &&
      ProfitDetailsMemo.data.filter((record: IProfitDetails) => {
        const code = record.product?.code.toLowerCase();
        const name = record.product?.name.toLowerCase();
        return name?.includes(text) || code?.includes(text);
      })
    );
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ProfitDetailsMemo, searchText]);

  const columns = useProfitDetailsReportColumns(
    pagination.pageIndex,
    pagination.pageSize,
    currencyCode
  );

  const table = useReactTable({
    data: error ? [] : filteredData ?? [],
    meta: {
      getRowStyles: (row: Row<IProfitDetails>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: ProfitDetailsMemo?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: ProfitDetailsMemo?.totalRecords ?? 0,
    searchText,
    setSearchText,
  };
};

export default useProfitDetailsReport;
