import React from 'react';
import { Formik, Form, Field, FieldProps } from 'formik';
import SearchIcon from '@mui/icons-material/Search';
import { TextField, InputAdornment, Button, Grid } from '@mui/material';
import { appColors } from '../../theme/appColors';

interface ISearchForm {
  setSearchText: (searchText: string) => void;
  placeholderName: string;
  buttonName: string;
}

const SearchField: React.FC<ISearchForm> = ({
  setSearchText,
  placeholderName,
  buttonName,
}) => {
  return (
    <Formik
      initialValues={{ searchText: '' }}
      onSubmit={(values) => {
        setSearchText(values.searchText);
      }}
    >
      <Form>
        <Field name="searchText">
          {({ field }: FieldProps<string>) => (
            <Grid
              container
              display="flex"
              flexDirection="row"
              item
              justifyContent="flex-end"
              key={3}
              sx={{ px: 0.5 }}
            >
              <TextField
                {...field}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon />
                    </InputAdornment>
                  ),
                }}
                placeholder={placeholderName}
                size="small"
                sx={{
                  width: 300,
                  mr: 1,
                  mb: 0,
                  '& .MuiOutlinedInput-root': {
                    borderRadius: 2,
                    '& fieldset': {
                      borderColor: appColors.darkGray[20],
                    },
                    '&:hover fieldset': {
                      borderColor: appColors.darkGreen[40],
                    },
                    '&.Mui-focused fieldset': {
                      borderColor: appColors.darkGreen[80],
                    },
                  },
                }}
                type="text"
                variant="outlined"
              />
              <Button
                sx={{
                  mb: 0,
                  border: 'none',
                  backgroundColor: appColors.darkGreen[20],
                  borderRadius: 2,
                  cursor: 'pointer',
                  width: 120,
                  height: 42,
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: appColors.greyishBlue[20],
                    borderColor: appColors.darkGreen[90],
                  },
                }}
                type="submit"
                variant="outlined"
              >
                {buttonName}
              </Button>
            </Grid>
          )}
        </Field>
      </Form>
    </Formik>
  );
};

export default SearchField;
